use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

const ALLOWED_HOST: &str = "feeds.example.com";
const NOTIFY_ATTEMPTS: u32 = 3;

struct Node;

/// Extract the host of an http(s) URL, lowercased, without port or userinfo.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved extension: record the input received on every call.
        state_rw::put("last-input", &feed_url);

        // Clock.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. Only ask for URLs on the allowlisted host: an
        // out-of-allowlist request is a trap at the boundary, not a value.
        let fetched: u32 = match host_of(&feed_url) {
            Some(h) if h == ALLOWED_HOST => match http_client::fetch(&feed_url) {
                Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
                Err(_) => 0,
            },
            _ => 0,
        };

        // Notification. The contract requires `notified == true`; the body never
        // fabricates that value. Retry a bounded number of times, and if the
        // notifier still refuses, trap rather than emit an output that violates
        // the contract.
        let message = format!(
            "heartbeat: t={} fetched={} chars",
            seconds, fetched
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
